// ── Reset SO (opname baru) ───────────────────
function resetStockOpname() {
  soSesi = null;
  closeModal('modal-laporan-so');
  document.getElementById('so-idle').classList.remove('hidden');
  document.getElementById('so-active').classList.add('hidden');
  document.getElementById('so-summary-grid').innerHTML = '';
  document.getElementById('so-scan-log').innerHTML = '';
  showToast('Sesi stock opname direset. Siap untuk opname baru.', 'info');
}

// ── Extend switchTab untuk SO ────────────────
const _origSwitchTab = switchTab;
window.switchTab = function(name) {
  const tabIds = ['stok', 'tambah', 'riwayat', 'stockopname'];
  tabIds.forEach(id => {
    const panel = document.getElementById(`tab-${id}`);
    const sb    = document.getElementById(`sb-${id}`);
    const bn    = document.getElementById(`bn-${id}`);
    if (id === name) {
      panel?.classList.remove('hidden');
      if (panel) { panel.style.animation='none'; void panel.offsetWidth; panel.style.animation=''; }
      sb?.classList.add('active');
      bn?.classList.add('active');
    } else {
      panel?.classList.add('hidden');
      sb?.classList.remove('active');
      bn?.classList.remove('active');
    }
  });
  if (name === 'riwayat') updateLogCounters();
};
